package com.company.platform.inventory.infrastructure;
import com.company.platform.shared.contracts.PlatformEvent;import java.time.Instant;import java.util.*;import org.slf4j.MDC;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;
@Component public class InventoryEventPublisher{private final KafkaTemplate<String,Object> kafka;public InventoryEventPublisher(KafkaTemplate<String,Object> k){kafka=k;}public void publish(String type,UUID tenantId,UUID aggregateId,Object payload){var auth=SecurityContextHolder.getContext().getAuthentication();String user=auth==null?"system":auth.getName();String correlation=Optional.ofNullable(MDC.get("correlationId")).orElseGet(()->UUID.randomUUID().toString());var body=Map.of("eventType",type,"aggregateType","Inventory","aggregateId",aggregateId.toString(),"data",payload);kafka.send(type.startsWith("Fulfillment")?"fulfillment.events":"inventory.events",aggregateId.toString(),new PlatformEvent<>(UUID.randomUUID().toString(),tenantId.toString(),user,correlation,Instant.now(),"inventory-service",body));}}
